const ui={overlay:document.querySelector('#overlay'),hud:document.querySelector('#hud'),play:document.querySelector('#play'),title:document.querySelector('#title'),overline:document.querySelector('#overline'),subtitle:document.querySelector('#subtitle'),fine:document.querySelector('#fine'),wave:document.querySelector('#wave'),hostiles:document.querySelector('#hostiles'),score:document.querySelector('#score'),objective:document.querySelector('#objective'),health:document.querySelector('#healthText'),healthBar:document.querySelector('#healthBar'),pulse:document.querySelector('#pulseText'),pulseBar:document.querySelector('#pulseBar'),message:document.querySelector('#message'),toast:document.querySelector('#toast'),damage:document.querySelector('#damage')};
let running=false,gameOver=false,clock=new THREE.Clock(),wave=0,score=0,health=100,spawnLeft=0,spawnTimer=0,intermission=0,shotTimer=0,pulseCooldown=0,pulseTime=0,invulnerable=0,hazardTimer=7,hazardState=0,hazardLane=0,messageTimer=0,elapsed=0;
const enemies=[],shots=[],particles=[],keys={},raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),aimPoint=new THREE.Vector3(0,1,-14),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),-1),clockDummy=new THREE.Vector3();
const playerMuzzle=new THREE.Vector3(.31,1.48,-1.34);
const cursor={x:innerWidth/2,y:innerHeight/2,fire:false};
function showMessage(text,duration=2.3){ui.message.textContent=text;ui.message.style.opacity='1';messageTimer=duration}
function blockMesh(x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;return m}
function spawnEnemy(){const heavy=(wave>=2&&Math.random()<.25)||(wave===3&&Math.random()<.36);const e=group(scene,(Math.random()-.5)*6.8,0,-28-Math.random()*12);e.userData={hp:heavy?4:2,heavy,fire:1.1+Math.random()*1.5,speed:heavy?1.1:1.5+Math.random()*.55,phase:Math.random()*6};const armor=heavy?mats.orange:mats.red;e.add(blockMesh(0,1.05,0,heavy?1.12:.82,1.12,.7,armor));e.add(blockMesh(0,1.78,-.02,.58,.58,.58,mats.dark));e.add(blockMesh(0,1.79,-.35,.35,.1,.08,mats.gold,false));e.add(blockMesh(-.23,.42,0,.24,.65,.3,mats.dark));e.add(blockMesh(.23,.42,0,.24,.65,.3,mats.dark));e.add(blockMesh(0,1.1,-.38,.26,.24,.08,heavy?mats.gold:mats.cyan,false));if(heavy){e.add(blockMesh(-.65,1.15,0,.3,.85,.82,mats.dark));e.add(blockMesh(.65,1.15,0,.3,.85,.82,mats.dark))}scene.add(e);enemies.push(e);spawnLeft--}
function addShot(pos,dir,enemy=false,damage=1){const mesh=new THREE.Mesh(sphereGeo,new THREE.MeshBasicMaterial({color:enemy?'#ff674b':'#b9fff4'}));mesh.scale.setScalar(enemy?.17:.12);mesh.position.copy(pos);scene.add(mesh);const glow=new THREE.PointLight(enemy?'#ff4a35':'#6fffea',enemy?1.5:2,.9);mesh.add(glow);shots.push({mesh,dir:dir.clone().normalize(),enemy,damage,speed:enemy?12:38,life:2.8})}
function puff(pos,color='#ffd18b',amount=8){for(let i=0;i<amount;i++){const m=new THREE.Mesh(boxGeo,new THREE.MeshBasicMaterial({color,transparent:true}));m.scale.setScalar(.08+Math.random()*.13);m.position.copy(pos);scene.add(m);particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*4,Math.random()*4,(Math.random()-.5)*4),life:.35+Math.random()*.5})}}
function removeEnemy(e,awarded=true){const ix=enemies.indexOf(e);if(ix<0)return;const pos=e.position.clone().add(new THREE.Vector3(0,1,0));puff(pos,e.userData.heavy?'#ff9b48':'#ffb56d',e.userData.heavy?15:9);scene.remove(e);enemies.splice(ix,1);if(awarded){score+=e.userData.heavy?250:100;ui.score.textContent=String(score).padStart(4,'0')}}
function fire(){if(shotTimer>0||!running)return;shotTimer=.16;const origin=player.localToWorld(playerMuzzle.clone());const target=aimPoint.clone();target.y=1.35;const dir=target.sub(origin);if(dir.length()<1)dir.set(0,0,-1);addShot(origin,dir,false,1);}
function activatePulse(){if(!running||pulseCooldown>0)return;pulseCooldown=8;pulseTime=.85;invulnerable=.9;showMessage('PRISM PULSE // RETURN TO SENDER',1.5);const origin=player.position.clone().add(new THREE.Vector3(0,1,0));const ring=new THREE.Mesh(new THREE.TorusGeometry(.8,.08,8,32),new THREE.MeshBasicMaterial({color:'#69fff0',transparent:true,opacity:.9}));ring.rotation.x=Math.PI/2;ring.position.copy(origin);scene.add(ring);particles.push({mesh:ring,ring:true,life:.65});for(let i=shots.length-1;i>=0;i--){const s=shots[i];if(s.enemy&&s.mesh.position.distanceTo(origin)<8){const d=aimPoint.clone().sub(s.mesh.position);addShot(s.mesh.position,d,false,2);scene.remove(s.mesh);shots.splice(i,1)}}for(const e of [...enemies])if(e.position.distanceTo(player.position)<5.5){e.userData.hp-=2;if(e.userData.hp<=0)removeEnemy(e);else puff(e.position.clone().add(new THREE.Vector3(0,1,0)),'#65fff0',5)}}
function setWave(n){wave=n;spawnLeft=[0,5,7,9][n];spawnTimer=.45;ui.wave.textContent=String(n).padStart(2,'0')+' / 03';ui.objective.textContent=['','CLEAR THE FIRST LINE','THE HEAVIES ARE INBOUND','SURVIVE THE LAST PUSH'][n];showMessage(['','WAVE 01 // SCOUTS INBOUND','WAVE 02 // HEAVY ARMOR DETECTED','FINAL PUSH // NO RETREAT'][n],2.7)}
function startGame(){for(const e of [...enemies])removeEnemy(e,false);for(const s of shots)scene.remove(s.mesh);shots.length=0;score=0;health=100;wave=0;spawnLeft=0;spawnTimer=.45;intermission=0;shotTimer=0;pulseCooldown=0;pulseTime=0;invulnerable=0;hazardTimer=6;hazardState=0;elapsed=0;gameOver=false;player.position.set(0,0,7);ui.score.textContent='0000';ui.health.textContent='100';ui.healthBar.style.width='100%';ui.overlay.classList.add('hide');ui.hud.style.display='block';if(matchMedia('(pointer:coarse)').matches)document.querySelector('#mobile').style.display='flex';else document.querySelector('#mobile').style.display='none';running=true;setWave(1);clock.getDelta();canvas.requestPointerLock?.()}

